<script setup lang="ts">
import {ref,watch,computed} from 'vue'
import {useI18n} from 'vue-i18n'
import {moduleRequest} from './api'
import ProductBarcodeScanner from '../shared-commerce/barcode/ProductBarcodeScanner.vue'
const props=defineProps<{base:string;productId:string;disabled:boolean}>(),{locale}=useI18n(),en=computed(()=>locale.value.startsWith('en')),codes=ref<string[]>([]),busy=ref(false),error=ref('')
let generation=0,pending:{barcode:string;remove:boolean;idempotencyKey:string}|null=null
watch([()=>props.base,()=>props.productId],async()=>{const own=++generation;pending=null;busy.value=true;error.value='';codes.value=[];try{const data=await moduleRequest<{barcodes:string[]}>(props.base,`/products/${props.productId}/barcodes`);if(own===generation)codes.value=data.barcodes}catch(e){if(own===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(own===generation)busy.value=false}},{immediate:true})
async function save(barcode:string,remove=false){if(props.disabled||busy.value)return;const own=generation;busy.value=true;error.value='';pending??={barcode,remove,idempotencyKey:crypto.randomUUID()};try{const data=await moduleRequest<{barcodes:string[]}>(props.base,`/products/${props.productId}/barcodes`,'POST',pending);if(own===generation){codes.value=data.barcodes;pending=null}}catch(e){if(own===generation){error.value=e instanceof Error?e.message:String(e);const status=(e as {status?:number}).status;if(status!==undefined&&status<500)pending=null}}finally{if(own===generation)busy.value=false}}
</script>
<template><section class="cards-panel"><h3>{{en?'Product barcodes':'商品条码号'}}</h3><p class="cards-muted">{{en?'Scan or enter the bottle barcode. Customers can then scan to select this product.':'扫描或填写瓶身商品条码，顾客之后扫码即可带出商品名称。'}}</p><p v-if="error" class="cards-error" role="alert">{{error}}</p><p v-if="busy" role="status">{{en?'Loading…':'处理中…'}}</p><div v-for="code in codes" :key="code" class="cards-actions"><span>{{code}}</span><button type="button" :disabled="disabled||busy||!!pending" @click="save(code,true)">{{en?'Remove barcode':'移除条码'}}</button></div><button v-if="pending" type="button" :disabled="busy||disabled" @click="save(pending.barcode,pending.remove)">{{en?'Retry previous operation':'重试上次条码操作'}}</button><ProductBarcodeScanner :disabled="disabled||busy||!!pending" @code="save($event)"/></section></template>
